#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_N 20000
#define MAX_LEN 10

static char passwords[MAX_N][MAX_LEN + 1];
static char unique_passwords[MAX_N][MAX_LEN + 1];
static int frequencies[MAX_N];

static int compare_strings(const void *a, const void *b) {
    return strcmp((const char *)a, (const char *)b);
}

static int find_frequency(const char *s, int unique_count) {
    int left = 0, right = unique_count;
    while (left < right) {
        int mid = left + (right - left) / 2;
        int cmp = strcmp(unique_passwords[mid], s);
        if (cmp < 0) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    if (left < unique_count && strcmp(unique_passwords[left], s) == 0) {
        return frequencies[left];
    }
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 0;
    }

    for (int i = 0; i < n; i++) {
        scanf("%10s", passwords[i]);
    }

    qsort(passwords, n, sizeof(passwords[0]), compare_strings);

    int unique_count = 0;
    for (int i = 0; i < n; ) {
        strcpy(unique_passwords[unique_count], passwords[i]);
        int j = i + 1;
        while (j < n && strcmp(passwords[i], passwords[j]) == 0) {
            j++;
        }
        frequencies[unique_count] = j - i;
        unique_count++;
        i = j;
    }

    long long answer = 0;

    for (int i = 0; i < n; i++) {
        int len = (int)strlen(passwords[i]);
        char seen[55][MAX_LEN + 1];
        int seen_count = 0;

        for (int start = 0; start < len; start++) {
            for (int length = 1; start + length <= len; length++) {
                char substring[MAX_LEN + 1];
                memcpy(substring, passwords[i] + start, (size_t)length);
                substring[length] = '\0';

                int already_seen = 0;
                for (int k = 0; k < seen_count; k++) {
                    if (strcmp(seen[k], substring) == 0) {
                        already_seen = 1;
                        break;
                    }
                }

                if (!already_seen) {
                    strcpy(seen[seen_count++], substring);
                    answer += find_frequency(substring, unique_count);
                }
            }
        }

        answer--;
    }

    printf("%lld\n", answer);
    return 0;
}
```

